//    並讓所有 prob 加起來 = 1。下面的數量、機率說明都會自動計算。

const TOTAL_TOYS = TOYS.length;
const REG_TOYS = TOYS.filter(t => t.type === "regular");
const HID_TOYS = TOYS.filter(t => t.type === "hidden");
const fmtPct = p => `${+(p * 100).toFixed(2)}%`;
const sumProb = list => list.reduce((a, t) => a + t.prob, 0);

// 把網頁上所有「幾款、幾 %」的文字依照 TOYS 自動填好
function fillToyCountTexts() {
  document.querySelectorAll(".jsTotalToys").forEach(el => (el.textContent = TOTAL_TOYS));
  document.querySelectorAll(".jsGuessLimit").forEach(el => (el.textContent = GUESS_WRONG_LIMIT));
  document.querySelectorAll(".jsRegCount").forEach(el => (el.textContent = REG_TOYS.length));
  document.querySelectorAll(".jsHidCount").forEach(el => (el.textContent = HID_TOYS.length));
  document.querySelectorAll(".jsRegPct").forEach(el => (el.textContent = fmtPct(sumProb(REG_TOYS))));
  document.querySelectorAll(".jsHidPct").forEach(el => (el.textContent = fmtPct(sumProb(HID_TOYS))));
  const regEach = [...new Set(REG_TOYS.map(t => fmtPct(t.prob)))].join("／");
  const hidEach = [...new Set(HID_TOYS.map(t => fmtPct(t.prob)))].join("／");
  document.querySelectorAll(".jsRegEach").forEach(el => (el.textContent = regEach));
  document.querySelectorAll(".jsHidEach").forEach(el => (el.textContent = hidEach));
}
fillToyCountTexts();

/**
 * =========================================================================
 * 2. 康軒版五上第六單元「異分母分數的加減」250 道已驗算題庫（第 106 題起為擴充題）
 * 格式說明：
 * - [w, n, d] 代表帶分數 w 又 n/d（若 w=0 則為真分數或假分數 n/d）
 * - 每道題目皆包含：題型分類、算式、正確答案、3 個學生常見迷思錯誤選項、解析說明
 * =========================================================================
 */
function gcd(a, b) { return b === 0 ? a : gcd(b, a % b); }
function lcm(a, b) { return (a * b) / gcd(a, b); }

function formatFracHTML(f) {
  const [w, n, d] = f;
  if (n === 0) return `<span class="whole-part">${w}</span>`;
  const fracPart = `<span class="frac"><span class="num">${n}</span><span class="den">${d}</span></span>`;
  if (w > 0) {
    return `<span class="mixed-num"><span class="whole-part">${w}</span>${fracPart}</span>`;
  }
  return fracPart;
}

function fracKey(f) {
  return `${f[0]}_${f[1]}_${f[2]}`;
}

function fracValue(f) {
  return f[0] + f[1] / f[2];
}

