// 不符合「最小公倍數在較大分母 4 倍以內」規則的舊題，題號保留但不再出題
const RETIRED_IDS = new Set([]);   // 舊的停用題已換成新題

// 啟動時自動驗算全部題目，確保零數學錯誤
const QUESTION_BANK = RAW_PROBLEMS.map((q, idx) => {
  const va = fracValue(q.a);
  const vb = fracValue(q.b);
  const vans = fracValue(q.ans);
  const calc = q.op === "+" ? va + vb : va - vb;
  if (Math.abs(calc - vans) > 1e-6) {
    console.error(`題庫第 ${idx + 1} 題驗算異常`, q);
  }
  return {
    id: idx + 1,
    cat: q.cat,
    op: q.op,
    a: q.a,
    b: q.b,
    ans: q.ans,
    distractors: [q.d1, q.d2, q.d3],
    hint: q.hint,
    text: q.text || "",
    unit: q.unit || ""
  };
}).filter(q => !RETIRED_IDS.has(q.id));

/**
 * =========================================================================
 * 3. 資料儲存層 (Firebase Firestore + LocalStorage 自動備援)
 * =========================================================================
 */

// 抽到重複公仔時可以換到的金幣
function toyCoinValue(toy) {
  return toy.coin || (toy.type === "hidden" ? 3 : 1);
}

function getOwnedUniqueCount(stu) {
  if (!stu || !stu.toys) return 0;
  return TOYS.filter(t => (stu.toys[t.id] || 0) > 0).length;
}
